/* Saga 35: 3D visualization -- full-width vertical stack */
main.viz3d-split {
    display: flex;
    flex-direction: column;
    overflow: hidden;
    padding: 0;
}
main.viz3d-split > .output {
    height: 30vh;
    min-height: 40px;
    overflow-y: auto;
    flex-shrink: 1;
    flex-grow: 0;
    padding: 8px 20px;
}
main.viz3d-split > .input-wrap {
    flex-shrink: 0;
}
main.viz3d-split > .resize-handle {
    height: 6px;
    background: var(--surface1);
    cursor: ns-resize;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
}
main.viz3d-split > .resize-handle::after {
    content: '';
    width: 40px;
    height: 3px;
    background: var(--surface2);
    border-radius: 2px;
}
main.viz3d-split > .resize-handle:hover {
    background: var(--blue);
}
main.viz3d-split > .stage3d-pane {
    flex: 1;
    min-height: 120px;
}
.stage3d-pane {
    display: flex;
    flex-direction: column;
    border-left: 1px solid var(--surface1);
    min-height: 300px;
}
.stage3d-wrap {
    position: relative;
    flex: 1;
    min-height: 0;
}
.stage3d-wrap canvas {
    width: 100%;
    height: 100%;
    display: block;
}
.stage3d-detail {
    background: var(--mantle);
    border-top: 1px solid var(--surface1);
    padding: 10px 16px;
    font-family: var(--mono);
    font-size: 13px;
    color: var(--text);
    max-height: 160px;
    overflow-y: auto;
}
.stage3d-detail-title {
    color: var(--peach);
    font-weight: bold;
    margin-bottom: 4px;
}
.stage3d-detail-row {
    color: var(--subtext0);
    line-height: 1.6;
}
.stage3d-detail-row strong { color: var(--text); }
/* Close-up inspector dialog opened from the yellow
   selection-pointer click. Modal layer + centered
   panel; matches the splash/tour visual language. */
.stage3d-inspector {
    position: fixed;
    inset: 0;
    z-index: 1000;
}
.stage3d-inspector-backdrop {
    position: absolute;
    inset: 0;
    background: rgba(20, 22, 30, 0.75);
    cursor: pointer;

