1	//! Saga 33 step 007: custom Yew hooks that allocate the App's
2	//! reactive state. Each `use_*` hook is small (under 25 LOC),
3	//! testable in isolation, and only touches the state it owns.
4	//! Together they replace 11+ inline `use_state` calls that
5	//! previously bloated `App::app`.
6	
7	use wasm_bindgen::JsCast;
8	use wasm_bindgen::closure::Closure;
9	use yew::prelude::*;
10	
11	use crate::app_state::{OnboardingState, Sessions, UiState, UploadState};
12	use crate::components::TutorialView;
13	use crate::scroll::scroll_and_focus;
14	use mlpl_wasm::WasmSession;
15	use mlpl_web_eval::state::HistoryEntry;
16	
17	/// Allocate the two isolated session scratchpads (main + tutorial)
18	/// via `use_mut_ref`. Stable identity across renders.
19	#[hook]
20	pub fn use_sessions() -> Sessions {
21	    Sessions {
22	        main: use_mut_ref(WasmSession::new),
23	        tutorial: use_mut_ref(WasmSession::new),
24	    }
25	}
26	
27	/// Allocate every reactive UI state slot in one `#[hook]`. Calling
28	/// this from `app()` is hooks-rules-safe because the inner
29	/// `use_state` calls happen in a fixed order on every render.
30	#[hook]
31	pub fn use_ui_state() -> UiState {
32	    UiState {
33	        history: use_state(Vec::<HistoryEntry>::new),
34	        tutorial_history: use_state(Vec::<HistoryEntry>::new),
35	        input_value: use_state(String::new),
36	        cmd_history: use_state(Vec::<String>::new),
37	        cmd_index: use_state(|| None::<usize>),
38	        dialog_open: use_state(|| false),
39	        lesson_idx: use_state(|| None::<usize>),
40	        tutorial_initial_view: use_state(|| TutorialView::Toc),
41	        path_state: use_state(|| None::<(Option<usize>, usize)>),
42	        completion_candidates: use_state(Vec::<String>::new),
43	        completion_selected: use_state(|| 0_usize),
44	        show_3d: use_state(|| false),
45	        editor_open: use_state(|| false),
46	        editor_content: use_state(String::new),
47	    }
48	}
49	
50	/// Allocate onboarding overlay state. Splash shows every
51	/// page load; dismiss is session-only (no localStorage).
52	#[hook]
53	pub fn use_onboarding_state() -> OnboardingState {
54	    OnboardingState {
55	        show_splash: use_state(|| true),
56	        show_tour: use_state(|| false),
57	        tour_step: use_state(|| 0_usize),
58	        show_whats_new: use_state(|| false),
59	        // Saga 82: persisted by the "what's new" close
60	        // callback in render-shell, which has no access to
61	        // BUILD_*.
62	        last_seen_version: env!("CARGO_PKG_VERSION").to_string(),
63	    }
64	}
65	
66	/// Allocate the upload-flow NodeRef + pending-name slot used by
67	/// the `:upload <name>` slash command + the file picker.
68	#[hook]
69	pub fn use_upload_state() -> UploadState {
70	    UploadState {
71	        input_ref: use_node_ref(),
72	        pending_name: use_state(|| None::<String>),
73	    }
74	}
75	
76	/// Mount the side-effect that scrolls the output pane to its
77	/// bottom and refocuses the REPL input after every history
78	/// append. Keyed on the active history handle so the effect
79	/// re-fires when the user switches between tutorial / main.
80	#[hook]
81	pub fn use_scroll_effect(active_history: UseStateHandle<Vec<HistoryEntry>>) {
82	    use_effect_with(active_history, |_| {
83	        scroll_and_focus();
84	        || ()
85	    });
86	}
87	
88	/// Wire a window-level Escape-key handler that closes the
89	/// doc dialog and the tutorial panel when either is open.
90	/// Same pattern the glossary popup already uses
91	/// (`crate::glossary_popup`) -- single window listener,
92	/// fired once at mount, closures `forget`ed because the App
93	/// host is mounted for the session lifetime. Setting a state
94	/// handle to its current value is a no-op, so the unconditional
95	/// `.set` calls don't cause spurious renders.
96	#[hook]
97	pub fn use_global_keydown(
98	    dialog_open: UseStateHandle<bool>,
99	    lesson_idx: UseStateHandle<Option<usize>>,
100	    show_tour: UseStateHandle<bool>,
101	    show_splash: UseStateHandle<bool>,
102	    show_3d: UseStateHandle<bool>,
103	) {
104	    use_effect_with((), move |_| {
105	        if let Some(window) = web_sys::window() {
106	            let closure = Closure::wrap(Box::new(move |e: web_sys::KeyboardEvent| {
107	                if e.key() == "Escape" {
108	                    show_splash.set(false);
109	                    show_tour.set(false);
110	                    dialog_open.set(false);
111	                    lesson_idx.set(None);
112	                }
113	                if crate::viz3d_toggle::is_3d_hotkey(e.ctrl_key(), e.code().as_str()) {
114	                    e.prevent_default();
115	                    show_3d.set(!*show_3d);
116	                }
117	            }) as Box<dyn FnMut(_)>);
118	            let _ = window
119	                .add_event_listener_with_callback("keydown", closure.as_ref().unchecked_ref());
120	            closure.forget();
121	        }
122	        || ()
123	    });
124	}
