502	function renderAttentionHeatmap(ud, viz) {
503	    const a = viz.attention;
504	    if (!a || !a.weights || !a.weights.length) {
505	        return '<div class="insp-hint">attention payload missing</div>';
506	    }
507	    const layout = a.layout || { rank: 'qk' };
508	    // numHeads = 1 for rank-2 qk, H for rank-3 head_qk, H for
509	    // rank-4 batch_head_qk (batch slice is a future saga).
510	    const numHeads = layout.rank === 'head_qk' || layout.rank === 'batch_head_qk'
511	        ? Math.max(1, layout.head | 0)
512	        : 1;
513	    if (inspectorHeadIdx < 0 || inspectorHeadIdx >= numHeads) inspectorHeadIdx = 0;
514	    const qLabels = (a.query_tokens || []).map(tokenLabel);
515	    const kLabels = (a.key_tokens || []).map(tokenLabel);
516	    const q = qLabels.length;
517	    const k = kLabels.length;
518	    // Offset into the flat weights array for the currently
519	    // selected head. Rank-2 qk has no head dimension, so the
520	    // offset is 0.
521	    const layerHeadOffset = numHeads > 1 ? inspectorHeadIdx * q * k : 0;
522	    const cellW = Math.max(20, Math.min(48, Math.floor(560 / Math.max(k, 8))));
523	    const cellH = cellW;
524	    const padL = 36, padT = 24, padR = 90;
525	    const w = padL + k * cellW + padR;
526	    const h = padT + q * cellH + 30;
527	    let svg = `<svg viewBox="0 0 ${w} ${h}" width="100%" style="max-width:680px;background:var(--mantle);border-radius:6px">`;
528	    // Key axis labels (top).
529	    for (let j = 0; j < k; j++) {
530	        const x = padL + j * cellW + cellW / 2;
531	        svg += `<text x="${x}" y="${padT - 8}" text-anchor="middle" font-size="11" font-family="var(--mono)" fill="var(--subtext1)">${escapeHtml(kLabels[j])}</text>`;
532	    }
533	    // Per-slice min/max so the viridis ramp stretches across
534	    // the visible range. Untrained attention is row-wise
535	    // softmax of randn noise: every cell sits near 1/N (0.023
536	    // for N=43), so clamping to [0, 1] collapses every color
537	    // to the same dark purple. Normalizing to [sliceMin,
538	    // sliceMax] makes the (still subtle) per-cell differences
539	    // visible.
540	    let sliceMin = Infinity, sliceMax = -Infinity;
541	    for (let idx = layerHeadOffset; idx < layerHeadOffset + q * k; idx++) {
542	        const v = a.weights[idx] || 0;
543	        if (v < sliceMin) sliceMin = v;
544	        if (v > sliceMax) sliceMax = v;
545	    }
546	    const sliceRange = sliceMax - sliceMin;
