//! Session init + execute for `mlpl-repl`. Keeps `main` a thin
//! init -> execute delegator: `init` builds the environment +
//! output sink from the parsed flags, and `execute` dispatches
//! to script mode or the interactive loop.

use std::path::PathBuf;

use mlpl_eval::Environment;

use crate::run_interactive;
use crate::script_mode;
use crate::svg_out::SvgOut;

/// Everything `execute` needs, assembled by `init`.
pub(crate) struct Session {
    pub env: Environment,
    pub svg_out: SvgOut,
    pub trace: bool,
    pub verbose: bool,
}

/// Split argv on the `--` separator: args before go to
/// mlpl-repl's flag parser, args after become the script's
/// `args()`. The separator itself is dropped. (Saga 31 step 003.)
pub(crate) fn split_separator(raw: &[String]) -> (Vec<String>, Vec<String>) {
    match raw.iter().position(|a| a == "--") {
        Some(i) => (raw[..i].to_vec(), raw[i + 1..].to_vec()),
        None => (raw.to_vec(), Vec::new()),
    }
}

/// Init phase: build the session from the parsed flags.
pub(crate) fn init(args: &[String], script_args: Vec<String>) -> Session {
    let flag = |name: &str| flag_value(args, name);
    let mut env = Environment::new();
    env.set_cli_args(script_args);
    if let Some(dir) = flag("--data-dir") {
        env.set_data_dir(PathBuf::from(dir));
    }
    if let Some(dir) = flag("--exp-dir") {
        env.set_exp_dir(PathBuf::from(dir));
    }
    Session {
        svg_out: SvgOut::new(flag("--svg-out").map(PathBuf::from)),
        trace: args.iter().any(|a| a == "--trace"),
        // Quiet by default; -v/--verbose echoes each script line.
        verbose: args.iter().any(|a| a == "-v" || a == "--verbose"),
        env,
    }
}

/// Execute phase: run a script (then exit with its code) or drop
/// into the interactive REPL.
