main.viz3d-split > .output {
    /* Give the REPL output roughly half the height so it
       stays readable when 3D is open. The stage3d-pane
       takes the rest (flex:1); the drag handle lets the
       user rebalance from this default. min-height keeps
       at least ~4 output lines visible even on a short
       viewport, so 3D can never squeeze the output down
       to just the prompt. */
    height: 45vh;
    min-height: 7em;
    overflow-y: auto;
    flex-shrink: 1;
    flex-grow: 0;
    padding: 8px 20px;
}
/* Scroll-up affordance: a sticky hint pinned to the top
   of the output pane so it's obvious there is earlier
   output above the visible (auto-scrolled-to-bottom)
   tail. Only in 3D split, where vertical space is tight. */
