(() => {
  const dlg = document.getElementById('stage3d-inspector');
  const body = document.getElementById('stage3d-inspector-body');
  if (!dlg || !body) return JSON.stringify({err:'no dialog'});
  // Simulate an open inspector on step 0.
  dlg.style.display = 'block';
  window.__viz_jump_step(0);            // selects step 0 + renders body
  const before = body.textContent.slice(0, 60);
  window.__stage3d_next();              // the on-screen "next" button
  const afterNext = body.textContent.slice(0, 60);
  window.__stage3d_prev();              // back to step 0
  const afterPrev = body.textContent.slice(0, 60);
  return JSON.stringify({
    before, afterNext, afterPrev,
    nextChangedBody: before !== afterNext,
    prevRestoredBody: before === afterPrev,
  });
})()

