        "ok" | "err" => Some(eval_result_ctor(name, args, env, trace)),
        "is_ok" | "is_err" | "unwrap" | "err_message" | "unwrap_or" => Some(
            crate::result_ops::eval_result_accessor(name, args, env, trace),
        ),
        "print" | "eprint" => Some(eval_print(name, args, env, trace)),
        "to_number" | "to_int" | "env" => Some(crate::result_ops::eval_string_to_result(
            name, args, env, trace,
        )),
        "args" => Some(eval_args(args, env)),
        "list_get" => Some(eval_list_get(args, env, trace)),
        "read_stdin" => Some(crate::eval_script::eval_read_stdin(args)),
        "read_stdin_lines" => Some(crate::eval_script::eval_read_stdin_lines(args)),
        "exit" => Some(crate::eval_script::eval_exit(args, env, trace)),
        _ => None,
    }
}

fn eval_list_len(
    args: &[Expr],
    env: &mut Environment,
    trace: &mut Option<&mut Trace>,
) -> Result<Value, EvalError> {
    if args.len() != 1 {
        return Err(EvalError::BadArity {
            func: "list_len".into(),
            expected: 1,
            got: args.len(),
        });
    }
    let v = eval_expr(&args[0], env, trace)?;
    match v {
        Value::StrList { items } => Ok(Value::Array(mlpl_array::DenseArray::from_scalar(
            items.len() as f64,
        ))),
        other => Err(EvalError::Unsupported(format!(
            "list_len: expected a string-list, got {}",
            value_kind(&other)
        ))),
    }
}

fn eval_result_ctor(
    name: &str,
    args: &[Expr],
    env: &mut Environment,
    trace: &mut Option<&mut Trace>,
) -> Result<Value, EvalError> {
    if args.len() != 1 {
        return Err(EvalError::BadArity {
            func: name.into(),
            expected: 1,
            got: args.len(),
        });
    }
    let payload = eval_expr(&args[0], env, trace)?;
    Ok(Value::Result {
        ok: name == "ok",
        payload: Box::new(payload),
    })
}

fn eval_print(
    name: &str,
    args: &[Expr],
    env: &mut Environment,
    trace: &mut Option<&mut Trace>,
) -> Result<Value, EvalError> {
    if args.is_empty() {
        return Err(EvalError::BadArity {
            func: name.into(),
            expected: 1,
            got: 0,
        });
    }
    // Variadic + space-joined (println-style) so labelled output
    // like `print("count:", n)` works without string concatenation:
    // each argument is rendered (strings literally, arrays/numbers
    // via Display) and joined with a single space. Returns the last
    // argument so `print(x)` still yields x.
    let mut parts = Vec::with_capacity(args.len());
    let mut last = Value::Array(DenseArray::from_scalar(0.0));
    for arg in args {
        let v = eval_expr(arg, env, trace)?;
        parts.push(format!("{v}"));
        last = v;
    }
    let line = parts.join(" ");
    if name == "print" {
        println!("{line}");
    } else {
        eprintln!("{line}");
    }
    Ok(last)
}

fn eval_args(args: &[Expr], env: &Environment) -> Result<Value, EvalError> {
    if !args.is_empty() {
        return Err(EvalError::BadArity {
            func: "args".into(),
            expected: 0,
            got: args.len(),
        });
    }
    Ok(Value::StrList {
        items: env.cli_args.clone(),
    })
}

fn eval_list_get(
    args: &[Expr],
    env: &mut Environment,
    trace: &mut Option<&mut Trace>,
) -> Result<Value, EvalError> {
    check_arity("list_get", args.len(), 2)?;
    let xs = eval_expr(&args[0], env, trace)?;
    let Value::StrList { items } = xs else {
        let msg = format!("list_get: expected a string-list, got {}", value_kind(&xs));
        return Err(EvalError::Unsupported(msg));
    };
    let i = parse_strlist_index(&args[1], env, trace)?;
    let (ok, s) = items.get(i).map_or_else(
        || {
            let msg = format!(
                "list_get: index {i} out of bounds (list has {} items)",
                items.len()
            );
            (false, msg)
        },
        |s| (true, s.clone()),
    );
    Ok(Value::Result {
        ok,
        payload: Box::new(Value::Str(s)),
    })
}

fn check_arity(name: &str, got: usize, expected: usize) -> Result<(), EvalError> {
    if got == expected {
        Ok(())
    } else {
        Err(EvalError::BadArity {
            func: name.into(),
            expected,
            got,
        })
    }
}

fn parse_strlist_index(
    arg: &Expr,
    env: &mut Environment,
    trace: &mut Option<&mut Trace>,
) -> Result<usize, EvalError> {
    let idx = eval_expr(arg, env, trace)?.into_array()?;
    if idx.rank() != 0 {
        return Err(EvalError::Unsupported(format!(
            "list_get: index must be a scalar, got rank {}",
            idx.rank()
        )));
    }
    let v = idx.data()[0];
    if v < 0.0 || v.fract() != 0.0 {
        return Err(EvalError::Unsupported(format!(
            "list_get: index must be a non-negative integer, got {v}"
        )));
    }
    Ok(v as usize)
}

