    if args.is_empty() {
        return Err(EvalError::BadArity {
            func: name.into(),
            expected: 1,
            got: 0,
        });
    }
    let mut vals: Vec<Value> = args
        .iter()
        .map(|a| eval_expr(a, env, trace))
        .collect::<Result<_, _>>()?;
