.output-line {
    color: var(--subtext1);
    white-space: pre;
    margin-left: 0;
    font-family: var(--mono);
    font-size: 15px;
}
.output-line.error {
    color: var(--red);
}
/* Saga 29 step 018: "this line is running" placeholder.
   The CSS animation runs on the browser compositor
   thread, so the spinner keeps turning even while the
   WASM eval blocks the main JS thread. */
