/// Plain-text summary of the sculpture the user is currently
/// inspecting (via the `window.__stage3d_context()` JS hook), or
/// empty when nothing is selected.
fn selection_context() -> String {
    js_sys::eval("window.__stage3d_context ? window.__stage3d_context() : ''")
        .ok()
        .and_then(|v| v.as_string())
        .unwrap_or_default()
}

/// Map a submitted line to the program to send to the server.
/// `:ask <question>` becomes an `llm_call` whose prompt is
/// prefixed with the current 3D-selection context (so the
/// question is about what the user is looking at, not
/// standalone); a bare expression passes through unchanged; any
/// other slash-command returns `None` to stay local.
fn connect_program(line: &str) -> Option<String> {
    let t = line.trim_start();
    if let Some(q) = t.strip_prefix(":ask ") {
        let ctx = selection_context();
        let prompt = if ctx.is_empty() {
            q.trim().to_string()
        } else {
            format!("Context (what the user is viewing): {ctx}. Question: {}", q.trim())
        };
        let esc = prompt.replace('\\', "\\\\").replace('"', "\\\"");
        return Some(format!("llm_call(\"{ASK_URL}\", \"{esc}\", \"{ASK_MODEL}\")"));
    }
    if t.starts_with(':') {
        return None;
    }
    Some(line.to_string())
}

