use yew::prelude::*;

use crate::help::help_text;
use mlpl_web_eval::state::{EntryKind, HistoryEntry};
use mlpl_web_handlers_upload::eval_deps::EvalDeps;
use mlpl_web_handlers_upload::upload_cmd::{handle_upload_command, parse_upload_command};

/// Single-line submit: thin wrapper that pipes the line through
/// the batch path so there is exactly one place that mutates
/// state. Calling `make_submit` N times in a tight loop USED
/// to drop N-1 history entries because each call did
/// `(*deps.history).clone()` -> push one -> `set(new)` --
/// inside one event tick every clone read the same snapshot
/// and only the last `set` won (Tutorial Run-All bug, May 7
/// 2026). Routing through `make_submit_batch` collapses any
/// number of lines into a single read-modify-write.
pub fn make_submit(deps: EvalDeps) -> Callback<String> {
    let batch = make_submit_batch(deps);
    Callback::from(move |line: String| batch.emit(vec![line]))
}

/// Evaluate every line in `lines` against the current session
/// in one pass, then commit all four state handles exactly
/// once. Empty/whitespace-only lines are skipped (matching
/// single-line submit semantics); `:clear` and `:help` are
/// honored mid-batch.
pub fn make_submit_batch(deps: EvalDeps) -> Callback<Vec<String>> {
    Callback::from(move |lines: Vec<String>| {
        let mut new_history = (*deps.history).clone();
        let mut new_cmds = (*deps.cmd_history).clone();
        let mut eval_queue: Vec<String> = Vec::new();
        for line in lines {
            classify_line(
                &deps,
                line,
                &mut new_history,
                &mut new_cmds,
                &mut eval_queue,
            );
        }
        if new_cmds.is_empty() {
            return;
        }
        deps.cmd_history.set(new_cmds);
        deps.cmd_index.set(None);
        deps.input_value.set(String::new());
        if eval_queue.is_empty() {
            deps.history.set(new_history);
            return;
        }
        process_next_eval(deps.clone(), new_history, eval_queue, 0);
    })
}

/// Classify one submitted line: `:clear` / `:3d ...` / upload commands
/// run immediately; everything else is queued for the WASM evaluator.
fn classify_line(
    deps: &EvalDeps,
    line: String,
    new_history: &mut Vec<HistoryEntry>,
    new_cmds: &mut Vec<String>,
    eval_queue: &mut Vec<String>,
) {
    let trimmed = line.trim();
    if trimmed.is_empty() {
        return;
    }
    new_cmds.push(trimmed.to_string());
    if trimmed == ":clear" {
        deps.session.borrow().clear();
        new_history.clear();
        if *deps.show_3d {
            let _ = js_sys::eval("window.__stage3d_clear && window.__stage3d_clear()");
        }
        return;
    }
    if let Some(cmd) = mlpl_web_viz3d::toggle::parse_3d_command(trimmed) {
        apply_3d_command(deps, cmd);
        return;
    }
    if let Some(name) = parse_upload_command(trimmed) {
        new_history.push(handle_upload_command(deps, trimmed, &name));
        return;
    }
    eval_queue.push(trimmed.to_string());
}

fn apply_3d_command(deps: &EvalDeps, cmd: mlpl_web_viz3d::toggle::Viz3dCmd) {
    match cmd {
        mlpl_web_viz3d::toggle::Viz3dCmd::On => deps.show_3d.set(true),
        mlpl_web_viz3d::toggle::Viz3dCmd::Off => deps.show_3d.set(false),
        mlpl_web_viz3d::toggle::Viz3dCmd::Reset => {
            let _ = js_sys::eval("window.__stage3d_reset_view && window.__stage3d_reset_view()");
        }
    }
}

/// Saga 29 step 018: recursive Timeout-yielding eval loop for
/// REPL submissions. Pushes a Running marker, yields, evals,
/// replaces marker with result, recurses to next line.
pub(crate) fn process_next_eval(
    deps: EvalDeps,
    mut history: Vec<HistoryEntry>,
    queue: Vec<String>,
    idx: usize,
) {
    if idx >= queue.len() {
        deps.history.set(history);
        return;
    }
    let line = queue[idx].clone();
    crate::running::push_running_marker(&mut history, &line);
    deps.history.set(history.clone());
    // Connect mode (?connect=<url>): route real expressions + the
    // `:ask` shortcut to mlpl-serve (async, server-side) so the
    // browser never blocks. Returns true when it took the eval.
    #[cfg(target_arch = "wasm32")]
    if crate::connect::try_connect_eval(&deps, &history, &queue, idx, &line) {
        return;
    }
    let deps_next = deps.clone();
    let queue_next = queue.clone();
    gloo::timers::callback::Timeout::new(0, move || {
        let entry = eval_one_line_with_3d(&deps_next, &line);
        history.pop();
        history.push(entry);
        process_next_eval(deps_next, history, queue_next, idx + 1);
    })
    .forget();
}

/// Saga 29 step 018: human-readable "this line is running"
/// caption tailored to the kind of line. Train blocks call out
/// the expected duration; everything else gets a generic
/// "evaluating..." marker that still tells the user the demo
/// hasn't hung. Saga 33 step 027: a "train 5"-shaped chunk
/// gets a chunk-sized caption so the user understands each
/// chunk is short and the page will recover between chunks;
/// large `train 30`+ blocks keep the long-duration warning.
pub(crate) fn running_message(line: &str) -> &'static str {
    let stripped = line.trim_start();
    if stripped.starts_with("train ") || stripped.starts_with("train{") {
        return crate::running::train_caption(stripped);
    }
    if stripped.starts_with("repeat ") {
        "looping... (this can take a few seconds)"
    } else if stripped.contains("predict_batch")
        || stripped.contains("apply(")
        || stripped.contains("attention_weights")
    {
        "evaluating... (forward pass through the trained model)"
    } else if stripped.contains("svg(") {
        "rendering visualization..."
    } else {
        "evaluating..."
    }
}

fn eval_one_line_with_3d(deps: &EvalDeps, line: &str) -> HistoryEntry {
    if line == ":help" || line.starts_with(':') {
        return eval_one_line(deps, line);
    }
    #[cfg(target_arch = "wasm32")]
    {
        let r = deps.session.borrow().eval_with_values(line);
        let is_error = r.display.starts_with("error:");
        if !is_error {
            let name = line.split('=').next().unwrap_or(line).trim().to_string();
            let info = mlpl_web_viz3d::events::build_shape_info_full(
                name,
                r.shape,
                r.values,
                r.string_list,
                r.viz_node,
            );
            mlpl_web_viz3d::events::emit(&mlpl_web_viz3d::events::Stage3dEvent {
                step_idx: 0,
                label: line.to_string(),
                output: info,
            });
        }
        return HistoryEntry {
            input: line.to_string(),
            output: r.display,
            is_error,
            kind: EntryKind::Command,
        };
    }
    #[cfg(not(target_arch = "wasm32"))]
    eval_one_line(deps, line)
}

/// `:history` output -- the recent REPL command lines, so the
/// user (and the `:ask` LLM, which also receives this) can see
/// what has been run.
fn history_listing(deps: &EvalDeps) -> String {
    let lines: Vec<String> = deps
        .history
        .iter()
        .filter(|e| matches!(e.kind, EntryKind::Command))
        .map(|e| format!("mlpl> {}", e.input.trim()))
        .collect();
    if lines.is_empty() {
        "(no commands run yet)".to_string()
    } else {
        lines.join("\n")
    }
}

fn eval_one_line(deps: &EvalDeps, trimmed: &str) -> HistoryEntry {
    if trimmed == ":help" {
        return HistoryEntry {
            input: trimmed.to_string(),
            output: help_text(),
            is_error: false,
            kind: EntryKind::Command,
        };
    }
    if trimmed == ":history" {
        return HistoryEntry {
            input: trimmed.to_string(),
            output: history_listing(deps),
            is_error: false,
            kind: EntryKind::Command,
        };
    }
    let result = deps.session.borrow().eval(trimmed);
    let is_error = result.starts_with("error:");
    HistoryEntry {
        input: trimmed.to_string(),
        output: result,
        is_error,
        kind: EntryKind::Command,
    }
}

//! Connect-mode eval dispatch. When the page is opened with
//! `?connect=<url>`, real expressions (and the `:ask` Ollama
//! shortcut) are sent to `mlpl-serve` and evaluated server-side,
//! so `llm_call` / MLX-GPU work run there and the browser never
//! blocks (or panics on WASM-unsupported HTTP/time). Whole module
//! is WASM-only; native builds compile it away.

#![cfg(target_arch = "wasm32")]

use mlpl_web_eval::state::{EntryKind, HistoryEntry};
use mlpl_web_handlers_upload::eval_deps::EvalDeps;

/// Default Ollama endpoint + model backing the `:ask` shortcut.
/// Overridable per page via `?ollama=<url>` / `?model=<name>` so
/// the demo can point at a remote GPU box + a bigger tool-capable
/// model (e.g. `?ollama=http://large12:11434&model=qwen2.5-coder:14b`).
/// mlpl-serve runs the `llm_call` server-side, so the target host
/// just has to be reachable from the server (no browser CORS).
const ASK_URL: &str = "http://localhost:11434";
const ASK_MODEL: &str = "qwen2.5:0.5b";

/// System/meta preamble prepended to every `:ask` so even broad
/// questions ("describe this environment") are grounded in what
/// MLPL is and what context the user can surface, rather than the
/// model guessing about generic OS/web environments.
const ASK_SYSTEM: &str = "You are an assistant embedded INSIDE the sw-MLPL REPL -- an APL/J/BQN-inspired array and tensor language for machine learning, with a 3D visualization playground (the REPL renders each result as a 3D sculpture: tensors as grids/bars, attention as heatmaps, models as Sankey diagrams). You are NOT a generic cloud/AWS/web assistant; EVERY question is about sw-MLPL. The user runs MLPL expressions in this REPL; `:help` lists the builtins and `:history` shows recent commands. The user's recent REPL activity and any selected 3D sculpture are provided below as your context -- use them. Answer concisely and specifically about sw-MLPL.";

/// Read a URL query parameter, falling back to `default` when it
/// is absent or empty. (`name` is a fixed literal, never user
/// input, so the inlined script is safe.)
fn query_param(name: &str, default: &str) -> String {
    let script = format!("new URLSearchParams(location.search).get('{name}') || ''");
    js_sys::eval(&script)
        .ok()
        .and_then(|v| v.as_string())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| default.to_string())
}

/// Plain-text summary of the sculpture the user is currently
/// inspecting (via the `window.__stage3d_context()` JS hook), or
/// empty when nothing is selected.
fn selection_context() -> String {
    js_sys::eval("window.__stage3d_context ? window.__stage3d_context() : ''")
        .ok()
        .and_then(|v| v.as_string())
        .unwrap_or_default()
}

/// Summarize the recent REPL activity (last few command/result
/// pairs) so `:ask` can answer questions about "what is being run
/// in the REPL" -- the Gemini-in-Colab experience. Newest entries
/// are kept; long outputs are truncated char-safely.
fn repl_history_context(history: &[HistoryEntry]) -> String {
    let mut recent: Vec<String> = history
        .iter()
        .rev()
        .filter(|e| matches!(e.kind, EntryKind::Command))
        .take(6)
        .map(|e| {
            let out: String = e.output.trim().chars().take(180).collect();
            format!("mlpl> {} => {}", e.input.trim(), out)
        })
        .collect();
    recent.reverse();
    recent.join(" | ")
}

/// Build the full `:ask` prompt: meta preamble + recent REPL
/// activity + the selected sculpture (if any) + the question.
fn build_ask_prompt(question: &str, history: &[HistoryEntry]) -> String {
    let mut p = ASK_SYSTEM.to_string();
    let recent = repl_history_context(history);
    if !recent.is_empty() {
        p.push_str(&format!(" Recent REPL activity (oldest first): {recent}."));
    }
    let sel = selection_context();
    if !sel.is_empty() {
        p.push_str(&format!(" Selected 3D sculpture: {sel}."));
    }
    p.push_str(&format!(" User question: {question}"));
    p
}

/// Map a submitted line to the program to send to the server.
/// `:ask <question>` becomes an `llm_call` whose prompt carries
/// the REPL/session context; a bare expression passes through; any
/// other slash-command returns `None` to stay local.
fn connect_program(line: &str, history: &[HistoryEntry]) -> Option<String> {
    let t = line.trim_start();
    if let Some(q) = t.strip_prefix(":ask ") {
        let prompt = build_ask_prompt(q.trim().trim_matches('"').trim(), history);
        let esc = prompt.replace('\\', "\\\\").replace('"', "\\\"");
        let url = query_param("ollama", ASK_URL);
        let model = query_param("model", ASK_MODEL);
        return Some(format!("llm_call(\"{url}\", \"{esc}\", \"{model}\")"));
    }
    if t.starts_with(':') {
        return None;
    }
    Some(line.to_string())
}

/// Dispatch `line` to the connected server (async) when a connect
/// URL is set and the line is server-eligible, chaining the rest
/// of the queue in the result callback so line order is kept.
/// Returns true when it took the eval; false to let the caller
/// evaluate locally.
pub(crate) fn try_connect_eval(
    deps: &EvalDeps,
    history: &[HistoryEntry],
    queue: &[String],
    idx: usize,
    line: &str,
) -> bool {
    let Some(program) = connect_program(line, history) else {
        return false;
    };
    let hist_handle = deps.history.clone();
    let deps_c = deps.clone();
    let queue_c = queue.to_vec();
    let line_c = line.to_string();
    let mut hist_c = history.to_vec();
    mlpl_web_eval::eval_wasm::connect_eval(
        &program,
        Box::new(move |result: String| {
            let is_error = result.starts_with("error:");
            hist_c.pop();
            hist_c.push(HistoryEntry {
                input: line_c.clone(),
                output: result,
                is_error,
                kind: EntryKind::Command,
            });
            hist_handle.set(hist_c.clone());
            crate::submit::process_next_eval(deps_c, hist_c, queue_c, idx + 1);
        }),
    )
}

//! mlpl-web App component + `start()` entrypoint. The App body
//! is intentionally a 1-to-4-line sequence of init / process /
//! render phases; each phase is a named helper in a sibling
//! file:
//!
//! - `app_hooks` -- custom hooks (`use_sessions`, `use_ui_state`,
//!   `use_upload_state`, `use_scroll_effect`).
//! - `app_active` -- pure `active_context(sessions, ui)`
//!   derivation.
//! - `app_callbacks` -- `build_callbacks(active, upload, ui)`.
//! - `app_log` -- side-effect `log_connect_mode()`.
//!
//! Saga 33 step 007.

use yew::prelude::*;

use crate::app_active::active_context;
use crate::app_hooks::{
    use_focus_after_splash, use_global_keydown, use_onboarding_state, use_scroll_effect,
    use_sessions, use_ui_state, use_upload_state,
};
use crate::app_log::{log_connect_mode, use_ask_hook};
use mlpl_web_render_shell::shell::render;
use mlpl_web_render_types::app_callbacks::build_callbacks;
use mlpl_web_render_types::args::RenderArgs;

/// Mount the Yew application. Called from `src/main_wasm_body.rs`
/// via `include!()` from `src/main.rs`.
pub fn start() {
    yew::Renderer::<App>::new().render();
}

#[function_component(App)]
fn app() -> Html {
    let sessions = use_sessions();
    let ui = use_ui_state();
    let upload = use_upload_state();
    let onboarding = use_onboarding_state();
    log_connect_mode();
    let active = active_context(&sessions, &ui);
    let callbacks = build_callbacks(&active, &upload, &ui);
    use_scroll_effect(active.history.clone());
    use_focus_after_splash(onboarding.show_splash.clone());
    use_ask_hook(callbacks.on_submit.clone());
    use_global_keydown(
        ui.dialog_open.clone(),
        ui.lesson_idx.clone(),
        onboarding.show_tour.clone(),
        onboarding.show_splash.clone(),
        ui.show_3d.clone(),
    );
    // Saga 82: only this crate's build.rs emits the BUILD_*
    // env vars; format them here and thread down via
    // RenderArgs.
    let build_info = format!(
        "v{}.{} \u{00b7} {} \u{00b7} {} \u{00b7} {}",
        env!("CARGO_PKG_VERSION"),
        env!("BUILD_COMMIT_COUNT"),
        env!("BUILD_HOST"),
        env!("BUILD_SHA"),
        env!("BUILD_TIMESTAMP"),
    );
    let version_label = format!(
        "v{}.{}",
        env!("CARGO_PKG_VERSION"),
        env!("BUILD_COMMIT_COUNT"),
    );
    render(RenderArgs::from_parts(
        callbacks,
        ui,
        upload,
        active,
        onboarding,
        build_info.into(),
        version_label.into(),
    ))
}

//! Connect-mode URL log helper + the `window.__mlpl_ask` JS
//! bridge. Both are window-level side-effects, kept out of
//! `app_hooks` so that module stays under its function-count cap.

use wasm_bindgen::JsCast;
use wasm_bindgen::closure::Closure;
use yew::prelude::*;

/// Log the connect-mode URL if one is present in the page
/// query string. WASM-only side-effect; on native this is a
/// no-op stub so call sites stay target-agnostic.
pub fn log_connect_mode() {
    #[cfg(target_arch = "wasm32")]
    if let Some(url) = mlpl_web_eval::eval::current_connect_url_from_window() {
        web_sys::console::log_1(&format!("[mlpl-web] connect mode: {url}").into());
    }
}

/// Expose `window.__mlpl_ask(question)` so JS (the 3D inspector's
/// "Ask" affordance) can submit a `:ask <question>` line through
/// the normal REPL pipeline -- which, in connect mode, routes to
/// the server-side LLM with the selection + REPL context attached.
#[hook]
pub fn use_ask_hook(on_submit: Callback<String>) {
    use_effect_with((), move |_| {
        if let Some(window) = web_sys::window() {
            let closure = Closure::wrap(Box::new(move |q: wasm_bindgen::JsValue| {
                if let Some(text) = q.as_string() {
                    on_submit.emit(format!(":ask {text}"));
                }
            }) as Box<dyn FnMut(wasm_bindgen::JsValue)>);
            let _ = js_sys::Reflect::set(
                &window,
                &wasm_bindgen::JsValue::from_str("__mlpl_ask"),
                closure.as_ref().unchecked_ref(),
            );
            closure.forget();
        }
        || ()
    });
}

