fn build_ask_system(history: &[HistoryEntry]) -> String {
    let mut p = ASK_SYSTEM.to_string();
    let recent = repl_history_context(history);
    if !recent.is_empty() {
        p.push_str(&format!(" Recent REPL activity (oldest first): {recent}."));
