use mlpl_serve::peers::{build_registry, parse_peer_arg};
use mlpl_serve::server::run;

pub(crate) const DEFAULT_BIND: &str = "127.0.0.1:6464";

pub(crate) struct Args {
    pub(crate) bind: SocketAddr,
    pub(crate) auth: AuthMode,
