/// `Some(o)`, the router is wrapped in a `tower-http`
/// `CorsLayer` that lets a browser on origin `o` reach
/// `/v1/*` (the connect-mode REPL in `apps/mlpl-web`). All
/// four args together replace the old 3-arg
/// `build_app_with_peers`; callers passing `None` for the
/// new arg get the legacy no-CORS behavior.
pub fn build_app_with_peers_cors(
    auth_mode: AuthMode,
    peers: crate::peers::PeerRegistry,
    static_dir: Option<&std::path::Path>,
    cors_origin: Option<String>,
    persist_path: Option<std::path::PathBuf>,
) -> Router {
    let sessions = new_map();
    let interrupts = new_interrupt_map();
    crate::persist::maybe_load(persist_path.as_deref(), &sessions, &interrupts);
    let state = AppState {
        sessions,
        interrupts,
        viz: new_store(),
        peers,
        peer_sessions: PeerSessionMap::default(),
        auth_mode,
        persist_path,
    };
    let mut router = Router::new()
        .route("/v1/health", get(health_handler))
        .route("/v1/sessions", post(create_session_handler))
        .route("/v1/sessions/:id", get(session_meta_handler))
        .route("/v1/sessions/:id/eval", post(eval_handler))
        .route(
            "/v1/sessions/:id/eval_stream",
            post(crate::sse::eval_stream_handler),
        )
        .route("/v1/sessions/:id/cancel", post(cancel_handler))
        .route("/v1/sessions/:id/inspect", get(inspect_handler))
        .route("/v1/viz", post(upload_handler))
        .route("/v1/viz/:id", get(get_handler))
        .with_state(state);
    if let Some(dir) = static_dir {
        let serve = tower_http::services::ServeDir::new(dir);
        router = router.nest_service("/sw-mlpl", serve);
    }
    if let Some(origin) = cors_origin {
        use axum::http::{Method, header};
        let origin_header = origin
            .parse::<axum::http::HeaderValue>()
            .expect("--cors-allow value must be a valid origin header");
        let layer = tower_http::cors::CorsLayer::new()
            .allow_origin(origin_header)
            .allow_methods([Method::GET, Method::POST, Method::OPTIONS])
            .allow_headers([header::AUTHORIZATION, header::CONTENT_TYPE]);
        router = router.layer(layer);
    }
    router
}

/// Bind the listener at `addr`, refuse insecure
/// non-loopback binds, then `axum::serve` the
/// router. Used by `main`; tests call `build_app`
/// directly + run on their own listener.
///
/// Saga R1 step 003: `peers` carries the
/// `--peer mlx=<url>`-derived registry built up by
/// `peers::build_registry` in `main`. An empty
/// registry means "no peer routing; device-scoped
/// blocks fall back to in-process dispatch."
/// Optional TLS configuration. `None` keeps the legacy
/// HTTP path; `Some(config)` switches to
/// `axum_server::bind_rustls` so the same listener
/// terminates TLS for the /v1 API and the static UI.
pub type TlsConfig = Option<axum_server::tls_rustls::RustlsConfig>;

pub async fn run(
    addr: SocketAddr,
    auth_mode: AuthMode,
    peers: crate::peers::PeerRegistry,
    static_dir: Option<std::path::PathBuf>,
    tls: TlsConfig,
    cors_origin: Option<String>,
    persist_path: Option<std::path::PathBuf>,
) -> Result<(), ServerError> {
    if !addr.ip().is_loopback() && auth_mode == AuthMode::Disabled {
        return Err(ServerError::InsecureBind { addr });
    }
    let app = build_app_with_peers_cors(
        auth_mode,
        peers,
        static_dir.as_deref(),
        cors_origin,
        persist_path,
    );
    match tls {
        Some(config) => axum_server::bind_rustls(addr, config)
            .serve(app.into_make_service())
            .await
            .map_err(ServerError::Bind),
        None => {
            let listener = tokio::net::TcpListener::bind(addr)
                .await
                .map_err(ServerError::Bind)?;
            axum::serve(listener, app).await.map_err(ServerError::Serve)
        }
    }
}

