27	/// Callback fired with the formatted result of one eval. Matches
28	/// the existing `WasmSession::eval(&str) -> String` shape: errors
29	/// arrive as `"error: <msg>"` strings, not as a separate Err
30	/// variant, so call sites can keep their existing
31	/// `result.starts_with("error:")` test for the red-text UI.
32	pub type ResultCb = Box<dyn FnOnce(String) + 'static>;
33	
34	/// Saga 21.5 step 007: per-iteration metric frame surfaced by
35	/// `RemoteEvaluator::eval_stream`. Mirrors the server-side
36	/// `SseEvent::Metric` payload.
37	#[derive(Debug, Clone)]
38	pub struct RemoteMetric {
39	    pub name: String,
40	    pub step: usize,
41	    pub value: f64,
42	}
43	
44	/// Saga 21.5 step 007: terminal SSE frame. `Done` carries the
45	/// final value + kind (matching the non-streaming `/eval`);
46	/// `Cancelled` carries the step + partial loss curve from a
47	/// `train { }` that observed a cancel; `Error` covers both
48	/// HTTP-level failures (auth, lex/parse) and runtime
49	/// `EvalError`s emitted as `event: error`.
50	#[derive(Debug)]
51	pub enum StreamOutcome {
52	    Done {
53	        value: String,
54	        kind: String,
55	    },
56	    Cancelled {
57	        step: usize,
58	        partial_losses: Vec<f64>,
59	    },
60	    Error {
61	        message: String,
62	    },
63	}
64	
65	/// Callback fired once per `event: metric` SSE frame during
66	/// streaming eval.
67	pub type MetricCb = Box<dyn FnMut(&RemoteMetric) + 'static>;
68	
69	/// Callback fired exactly once with the terminal outcome of a
70	/// streaming eval.
71	pub type StreamCb = Box<dyn FnOnce(StreamOutcome) + 'static>;
72	
73	/// One-line evaluator. The WASM impl runs in-process; the REST
74	/// impl POSTs to a remote `mlpl-serve`. Both invoke `on_result`
75	/// exactly once.
76	pub trait Evaluator {
77	    /// Evaluate `program` and surface the formatted result via
78	    /// `on_result`. Implementations decide whether the callback
79	    /// fires immediately (WASM) or later (REST).
80	    fn eval(&self, program: &str, on_result: ResultCb);
81	
82	    /// Reset the evaluator's session state. For the REST impl,
83	    /// drops the cached session id + token so the next `eval`
84	    /// will mint a fresh server-side session.
85	    fn clear(&self);
86	}
87	
88	/// In-process WASM evaluator: thin wrapper over `WasmSession`.
89	/// Reuses an existing session (`from_session`) so the rest of
90	/// the web app keeps direct access for demos / tutorials that
91	/// run many lines in a tight loop.
92	pub struct WasmEvaluator {
93	    session: Rc<RefCell<mlpl_wasm::WasmSession>>,
94	}
95	
96	impl WasmEvaluator {
97	    #[must_use]
98	    pub fn from_session(session: Rc<RefCell<mlpl_wasm::WasmSession>>) -> Self {
99	        Self { session }
100	    }
101	}
102	
103	impl Evaluator for WasmEvaluator {
104	    fn eval(&self, program: &str, on_result: ResultCb) {
105	        let result = self.session.borrow().eval(program);
106	        on_result(result);
107	    }
108	    fn clear(&self) {
109	        self.session.borrow().clear();
110	    }
111	}
