113	/// REST evaluator backed by a remote `mlpl-serve`. Lazily creates
114	/// a session on first `eval`. Native build uses
115	/// `reqwest::blocking`; the WASM build uses `gloo::net` (see
116	/// `eval_wasm.rs`).
117	pub struct RemoteEvaluator {
118	    base_url: String,
119	    state: Rc<RefCell<Option<RemoteSession>>>,
120	}
121	
122	/// Server-side session id + bearer token, minted on first eval.
123	#[derive(Clone)]
124	pub struct RemoteSession {
125	    pub session_id: String,
126	    pub token: String,
127	}
128	
129	impl RemoteEvaluator {
130	    #[must_use]
131	    pub fn new(base_url: impl Into<String>) -> Self {
132	        Self {
133	            base_url: base_url.into(),
134	            state: Rc::new(RefCell::new(None)),
135	        }
136	    }
137	
138	    #[must_use]
139	    pub fn base_url(&self) -> &str {
140	        &self.base_url
141	    }
142	
143	    /// Snapshot of the current server-side session id, if one
144	    /// has been minted. Used by `cancel` to address the in-flight
145	    /// stream.
